import{_ as t,o,a as i,ag as a}from"./chunks/framework.Do1Zayaf.js";const g=JSON.parse('{"title":"Roxie Optimization Backlog","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/optimizations.md","filePath":"aidoc/roxie-kb/optimizations.md","lastUpdated":1779520499000}'),r={name:"aidoc/roxie-kb/optimizations.md"};function n(s,e,l,c,d,h){return o(),i("div",null,e[0]||(e[0]=[a('<h1 id="roxie-optimization-backlog" tabindex="-1">Roxie Optimization Backlog <a class="header-anchor" href="#roxie-optimization-backlog" aria-label="Permalink to &quot;Roxie Optimization Backlog&quot;">​</a></h1><blockquote><p><strong>Note</strong>: This document tracks significant architectural and performance optimizations discovered during analysis. It is explicitly heavily weighted toward Index Operations, Half Keyed Joins, and Splitter contention.</p></blockquote><p><strong>General Concurrency Context</strong>:</p><ul><li>Typically, each Roxie server handles <strong>10-20 concurrent queries</strong>.</li><li>The <strong>number of activities in a query varies significantly</strong>: simple queries might have around 100 activities, while complex queries can have <strong>tens of thousands</strong>.</li><li>The <strong>index operations</strong> resulting from these queries can lead to exponentially more active worker threads.</li><li>The <strong>optimum number of worker threads</strong> remains a critical topic for investigation and is heavily dependent on three key factors: <ol><li>The effectiveness of the internal node caches.</li><li>The time required to decompress nodes.</li><li>The speed of the underlying storage (e.g., NVME vs. Remote Storage).</li></ol></li></ul><hr><h2 id="_1-critical-half-keyed-joins-splitters" tabindex="-1">1. CRITICAL: Half Keyed Joins &amp; Splitters <a class="header-anchor" href="#_1-critical-half-keyed-joins-splitters" aria-label="Permalink to &quot;1. CRITICAL: Half Keyed Joins &amp; Splitters&quot;">​</a></h2><p><strong>Context</strong>: Half Keyed joins are the most critical join type in Roxie. Contention within these joins heavily impacts concurrent scale. Splitters are similarly foundational and contention hurts many queries.</p><ul><li><strong>Refactor <code>groupsCrit</code> in Half Keyed Joins</strong>: <ul><li><strong>Current State</strong>: <code>processCompletedGroups()</code> in <code>CRoxieServerKeyedJoinBase</code> holds <code>groupsCrit</code> during user-defined transformations (<code>doJoinGroup()</code>). This heavily stalls the main puller thread.</li><li><strong>Action</strong>: Move execution of <code>doJoinGroup()</code> strictly outside the critical section in <code>processCompletedGroups()</code>. Dequeue ready groups into a thread-isolated list while holding <code>groupsCrit</code>, release the lock, and then perform the data parsing/serialization sequentially.</li></ul></li><li><strong>Splitters Analysis (<code>CRoxieServerThroughSpillActivity</code>) Lock Contention</strong>: <ul><li><strong>Current State</strong>: Splitters buffer rows for downstream pipelines using a global <code>QueueOf</code> wrapper. Every single downstream thread making a <code>nextRow()</code> call contends on two locks (<code>crit</code> and <code>crit2</code>). Worse, determining if a row can be discarded involves an $O(N)$ scan of all outputs (<code>isLastTailReader()</code> and <code>minIndex()</code>) that executes <em>while holding the <code>crit</code> lock</em>. While splitters typically have &lt; 10 outputs, large numbers (massive fan-outs) are not impossible, making this $O(N)$ scan within a lock a severe tail-risk. In a Single-VM Topology B limit, this creates compounding OS-level lock stalls across channels.</li><li><strong>Action - RefCount Buffers</strong>: Wrap buffered <code>RoxieRow</code> allocations in atomic reference counts <code>std::atomic&lt;uint32_t&gt; refCount = NumOutputs</code>. Let downstream pipelines pull atomically without locking (<code>crit</code>), decrementing the refCount and cleanly discarding the row when it reaches 0.</li><li><strong>Action - O(1) Tail Resolution</strong>: Replace the linear N-scan in <code>minIndex</code> with a Min-Heap tracker sorted by reader offset, immediately transforming the lock period from $O(N)$ to $O(1)$.</li><li><strong>Action - Push Model</strong>: Follow the newer <code>IStrandJunction</code> architecture. Refactor splitters directly to async Push execution where the parent thread dispatches rows down the multiple pipes unblocked, rather than N parallel downstream consumers blocking each other waiting to Pull.</li></ul></li></ul><h2 id="_2-very-important-index-reads-execution-jhtree" tabindex="-1">2. VERY IMPORTANT: Index Reads &amp; Execution (<code>jhtree</code>) <a class="header-anchor" href="#_2-very-important-index-reads-execution-jhtree" aria-label="Permalink to &quot;2. VERY IMPORTANT: Index Reads &amp; Execution (`jhtree`)&quot;">​</a></h2><p><strong>Context</strong>: Index operations are the primary driver of Roxie performance. File-based reads (CSV/XML) are rarely used and should be ignored for optimizations.</p><ul><li><strong>Asynchronous <code>jhtree</code> Decompression</strong>: <ul><li><strong>Current State</strong>: Index reads halt the query thread when a compressed block must be read and deflated from disk.</li><li><strong>Action</strong>: Dispatch block decompression to a background CPU thread-pool in <code>jhtree</code>. Leave the primary query threads purely focused on choreography and graph traversal.</li></ul></li></ul><h2 id="_3-very-important-memory-allocation-roxiemem-jemalloc" tabindex="-1">3. VERY IMPORTANT: Memory &amp; Allocation (<code>roxiemem</code> &amp; <code>jemalloc</code>) <a class="header-anchor" href="#_3-very-important-memory-allocation-roxiemem-jemalloc" aria-label="Permalink to &quot;3. VERY IMPORTANT: Memory &amp; Allocation (`roxiemem` &amp; `jemalloc`)&quot;">​</a></h2><p><strong>Context</strong>: Standard allocations during hot paths cause Tcache thrashing and bin-lock contention across concurrent joins.</p><ul><li><strong>Thread-Local Caching for <code>roxiemem</code></strong>: <ul><li><strong>Current State</strong>: High-concurrency allocations serialize heavily onto <code>heapletLock</code> in <code>CChunkedHeap::doAllocateRow</code>.</li><li><strong>Action</strong>: Introduce a thread-local small queue (like TCMalloc/Jemalloc) of pre-allocated <code>roxiemem</code> chunks. Drain from thread-local without the <code>heapletLock</code>, falling back to <code>heapletLock</code> only on a cache-miss.</li></ul></li><li><strong>Lock-Free <code>activeBufferCS</code> Pools</strong>: <ul><li><strong>Action</strong>: Replace <code>CriticalSection activeBufferCS</code> in <code>CChunkingRowManager</code> with a lock-free ring-buffer since data payload lifecycles are identical and constant size.</li></ul></li></ul><h2 id="_4-important-soapcall-and-query-invariants" tabindex="-1">4. IMPORTANT: <code>soapcall</code> and Query Invariants <a class="header-anchor" href="#_4-important-soapcall-and-query-invariants" aria-label="Permalink to &quot;4. IMPORTANT: `soapcall` and Query Invariants&quot;">​</a></h2><p><strong>Context</strong>: While standard XML/Parse activities are rarely used, <code>soapcall</code> is heavily used and relies on XML/JSON translation.</p><ul><li><strong>Hoist <code>CXMLMaker</code> Compilation</strong>: <ul><li><strong>Current State</strong>: XML parsing paths repetitively parse XPath schemas per record inside execution loops, dumping the state machine afterward.</li><li><strong>Action</strong>: For heavily used <code>soapcall</code> flows (and similar XML abstractions), hoist the <code>CXMLMaker</code> template generation into the Factory constructor. Ensure the layout map is calculated once at query-load, allowing execution threads to simply stream data through the invariant state machine.</li></ul></li></ul><h2 id="_5-network-cluster-transport-mechanics" tabindex="-1">5. NETWORK: Cluster Transport Mechanics <a class="header-anchor" href="#_5-network-cluster-transport-mechanics" aria-label="Permalink to &quot;5. NETWORK: Cluster Transport Mechanics&quot;">​</a></h2><p><strong>Context</strong>: Server-to-Worker dispatch and Worker-to-Server Result merging.</p><ul><li><strong>TCP Message Collating Simplification</strong>: <ul><li><strong>Action</strong>: Bypass the complex gap-checking (<code>PacketSequencer</code>) and background collator threads cleanly when the topology operates natively over TCP. Delegate back-pressure heavily to the OS limits via <code>CSocketTarget::writeAsync</code>, stripping legacy UDP network throttles.</li></ul></li><li><strong>Parallelize Outbound <code>ROQ</code> Serialization</strong>: <ul><li><strong>Action</strong>: The background thread <code>RoxieThrottledPacketSender</code> single-threads payload serialization. Move <code>.serialize()</code> execution into the concurrent dispatch threads <em>before</em> the throttled network loop.</li></ul></li><li><strong>Remote Result Merge Heap Trashing (<code>CRemoteResultMerger</code>)</strong>: <ul><li><strong>Action</strong>: Batch the <code>makeHeap()</code>/<code>remakeHeap()</code> ops when assembling unsequenced UDP packets on the server side to bypass crippling min-heap thrashing during high-incast remote execution.</li></ul></li><li><strong>Eliminate Application-Level Fragmentation &amp; Reassembly</strong>: <ul><li><strong>Current State</strong>: Roxie uses <code>UdpPacketHeader</code> masking to chunk large data streams at the software tier (which even bleeds over into TCP bridging via <code>CTcpPacketCollator</code>).</li><li><strong>Action</strong>: Rely on TCP&#39;s reliable byte-stream abstraction to cleanly stream unchunked memory structures, deleting the sequencing maps and collator overhead on the receivers.</li></ul></li><li><strong>Strip RTS/CTS Throttling Paradigms</strong>: <ul><li><strong>Current State</strong>: UDP incast requires extreme lock-bound Request-to-Send (RTS) and Clear-to-Send (CTS) mechanisms to throttle dispatch.</li><li><strong>Action</strong>: Let TCP kernel window sizes naturally provide backpressure. Remove the RTS/CTS permit queue layer entirely to drop mutex/CAS contention on dispatch threads.</li></ul></li><li><strong>Event-Driven Socket Death Detection</strong>: <ul><li><strong>Current State</strong>: Network failures are detected by a polling thread that tracks custom UDP ping/pong elapsed timestamps across the topology.</li><li><strong>Action</strong>: Use socket-level <code>epoll</code> (<code>EPOLLRDHUP</code>/<code>EPOLLERR</code>) and <code>SO_KEEPALIVE</code> on persistent TCP connections. Turn node crash resolution from a delayed ping-timeout event into an instantaneous OS-level interrupt.</li></ul></li><li><strong>Zero-Copy Network Serialization (Scatter-Gather)</strong>: <ul><li><strong>Current State</strong>: Data maps into heavily managed discrete <code>DataBuffer</code> payloads in memory to fit UDP envelopes.</li><li><strong>Action</strong>: Leverage continuous sockets with <code>writev()</code> (Scatter-Gather I/O) to write discrete header structs and payload memory pointers straight into the OS kernel without an intermediate chunking <code>memcpy</code>.</li></ul></li></ul><h2 id="_6-child-queries-subgraph-execution-cactivitygraph" tabindex="-1">6. CHILD QUERIES: Subgraph Execution (<code>CActivityGraph</code>) <a class="header-anchor" href="#_6-child-queries-subgraph-execution-cactivitygraph" aria-label="Permalink to &quot;6. CHILD QUERIES: Subgraph Execution (`CActivityGraph`)&quot;">​</a></h2><p><strong>Context</strong>: Activities like <code>PROJECT</code>, <code>LOOP</code>, <code>NORMALIZE</code> or child-datasets often trigger child subgraphs <em>per-row</em>. High-volume queries will execute tens of thousands of child graph instances rapidly.</p><ul><li><strong>Remove Redundant <code>evaluateCrit</code> in <code>CActivityGraph</code></strong>: <ul><li><strong>Current State</strong>: Every time <code>CActivityGraph::evaluate</code> fires, it locks <code>evaluateCrit</code>. However, <code>CProxyActivityGraph</code> already enforces thread-exclusivity per child instance, and serial queries run single-threaded.</li><li><strong>Action</strong>: Remove the lock (or conditionally bypass it), saving thousands of atomic context switches per second on the hot path.</li></ul></li><li><strong>Pool Volatile <code>CGraphResults</code> and OS <code>CriticalSection</code> Instantiations</strong>: <ul><li><strong>Current State</strong>: <code>evaluate()</code> dynamically allocates a <code>new CGraphResults</code> per query. This object contains a Windows/POSIX <code>CriticalSection</code> member. Dynamically allocating and destroying OS-level lock primitives per execution absolutely thrashes <code>jemalloc</code>.</li><li><strong>Action</strong>: <ol><li>Pool <code>CGraphResults</code> via a lock-free cache. Override <code>Release()</code> to wipe internal state and recycle the envelope instead of destructing.</li><li>Check if the <code>CriticalSection</code> inside <code>CGraphResults</code> is strictly necessary on read paths; if the parent sequence consumes data iteratively unshared, elide the lock.</li></ol></li></ul></li><li><strong>Lock-Free Instance Popping in <code>CProxyActivityGraph</code></strong>: <ul><li><strong>Current State</strong>: When running parallel subgraphs, <code>CProxyActivityGraph::evaluate</code> takes a global <code>graphCrit</code> lock <em>twice per row</em>: once to <code>stack.popGet()</code> an execution graph, and again to <code>stack.append()</code> it back. Under a Single-VM Topology B limit, this crushes parallelism because hundreds of threads block on a single lock just to check out an execution context.</li><li><strong>Action</strong>: Replace the <code>CIArrayOf stack</code> guarded by a mutex with an <code>std::atomic</code> lock-free Treiber stack. Furthermore, aggressively pre-warm/pre-allocate these graph contexts during <code>onCreate</code> initialization rather than lazily allocating them inside the hot execution loop.</li></ul></li></ul><h2 id="_7-files-and-caching-multi-part-logic-os-page-caching-and-eviction" tabindex="-1">7. FILES AND CACHING: Multi-part Logic, OS Page Caching, and Eviction <a class="header-anchor" href="#_7-files-and-caching-multi-part-logic-os-page-caching-and-eviction" aria-label="Permalink to &quot;7. FILES AND CACHING: Multi-part Logic, OS Page Caching, and Eviction&quot;">​</a></h2><p><strong>Context</strong>: File resolution and caching heuristics heavily dictate max throughput. Because of compression and physical distribution, file sizes and mapping structures can create request avalanches and severe cache pollution.</p><ul><li><strong>Agent Request Avalanche (Logical to Physical Mapping)</strong>: <ul><li><strong>Current State</strong>: A single abstract file &quot;x&quot; inside a query may map dynamically to multiple underlying logical files. A keyed join targeting that abstract file triggers index requests against <em>each</em> underlying logical file individually.</li><li><strong>Action - Mitigate Agent Thread Walls</strong>: The maximum throughput and resilience of a Roxie cluster under load is fundamentally capped by the <em>number of generated Agent Requests</em>. We need to investigate ways to batch, group, or intelligently consolidate logical-to-physical traversal mechanisms ahead of dispatch so complex joins don&#39;t trigger cascading agent request explosions.</li></ul></li><li><strong>Internal Node Cache vs. Linux Page Cache Interference</strong>: <ul><li><strong>Current State</strong>: The Linux Page Cache holds natively compressed nodes straight off disk, while the Roxie internal node cache (<code>roxiemem</code>) holds fully decompressed pages. <ul><li>A larger Linux Page Cache holds more historical nodes (avoiding catastrophic 150µs disk I/O penalties).</li><li>A larger Internal Cache reduces CPU load by avoiding constant re-decompression but sacrifices raw density footprint.</li></ul></li><li><strong>Action - Tuning Overlap</strong>: If index blocks are stored uncompressed (Size On Disk == Size In Memory), half the system&#39;s memory is wasted duplicating blocks between the OS and Roxie. Track block statuses and instruct Roxie to dynamically minimize the internal cache for 1:1 footprint indexes.</li></ul></li><li><strong>&quot;Noisy Neighbor&quot; Cache Eviction Pollution</strong>: <ul><li><strong>Current State</strong>: Heavy, long-running queries that touch a vast number of files aggressively cycle memory blocks. In a mixed workload environment, these sweeps flush the &quot;hot&quot; data used by fast, highly concurrent interactive queries out of both the Linux Page Cache and the internal Roxie Node Cache.</li><li><strong>Action - Partitioning &amp; Priority Caching</strong>: Future architectures must implement priority-tiering (Quality of Service) for cache domains. Either partition the <code>roxiemem</code> cache blocks per-query-class or implement a strict MRU/LRU isolation tier where &quot;Low Priority&quot; operations are explicitly barred from evicting cached blocks belonging to &quot;High Priority&quot; endpoints.</li><li>Make writes to the disk cache asynchronous</li><li>Ensure reads and writes to the disk cache do not lock each other.</li></ul></li></ul><h2 id="_8-memory-architecture-roxiemem-sub-allocation-alignment" tabindex="-1">8. MEMORY ARCHITECTURE: <code>roxiemem</code> Sub-Allocation &amp; Alignment <a class="header-anchor" href="#_8-memory-architecture-roxiemem-sub-allocation-alignment" aria-label="Permalink to &quot;8. MEMORY ARCHITECTURE: `roxiemem` Sub-Allocation &amp; Alignment&quot;">​</a></h2><p><strong>Context</strong>: <code>roxiemem</code> operates by carving up large OS pages into smaller, sub-allocated row chunks to avoid OS-level allocation overhead. While efficient for density, the strict topological alignment of these pages introduces insidious CPU-level bottlenecks under extreme concurrency (Topology A &amp; B).</p><ul><li><strong>Cache Set Thrashing (Alignment Collisions)</strong>: <ul><li><strong>Current State</strong>: Large OS pages (e.g., 2MB) mathematically share the exact same lower-order bit patterns. When <code>roxiemem</code> sub-allocates structures at identical offsets within these pages, it guarantees that concurrent accesses hit the <em>exact same Cache Sets</em> in the CPU&#39;s N-way associative L1/L2 caches. This forces threads to aggressively evict each other&#39;s hot data, even though they aren&#39;t touching the same actual bytes.</li><li><strong>Action - Cache Coloring</strong>: Introduce randomized padding offsets (Cache Coloring) at the start of each large page. By shifting the initial allocation boundaries by differing cache-line widths (e.g., +64, +128 bytes), memory naturally distributes across the CPU cache sets, stopping the eviction loop.</li></ul></li><li><strong>False Sharing on Small Chunks</strong>: <ul><li><strong>Current State</strong>: If <code>roxiemem</code> allocates small payload structures (e.g., 16 or 32 bytes) contiguously, different worker threads might end up owning rows that reside on the exact same 64-byte L1 CPU cache line. When Thread A writes to its row, it hardware-invalidates Thread B&#39;s CPU cache line, creating invisible but catastrophic memory stalls across cores.</li><li><strong>Action - Padding &amp; Bulk Dealing</strong>: Enforce strict <code>alignas(64)</code> boundaries (or <code>CACHE_LINE_SIZE</code> padding) for heavily mutated structures. To save memory, deal allocations to threads in bulk contiguous chunks so a single thread exclusively owns the entire cache-line neighborhood avoiding cross-thread overlaps.</li></ul></li><li><strong>Sub-Allocator Lock Contention</strong>: <ul><li><strong>Current State</strong>: As multiple threads attempt to carve rows out of the same large page pool, they inevitably collide on central allocator locks (<code>heapletLock</code>) controlling that specific page manager map.</li><li><strong>Action - Strict TLABs</strong>: Enforce strict <strong>Thread-Local Allocation Buffers (TLABs)</strong>. Assign entire large pages to specific threads. The thread sub-allocates from its private page completely lock-free until exhausted, only hitting the central spinlock to request a fresh page from the OS.</li></ul></li></ul>',29)]))}const p=t(r,[["render",n]]);export{g as __pageData,p as default};
